18	.login { padding:10px; background-color:#fff; float:right; width:390px;}
19	.login ul li { font-size:12px; color:#6d6d6d;float:left; line-height:24px; padding-right:15px;}
20	.login ul li span { font-size:12px; color:#fda701; font-weight:bold; text-align:center;}
21	.login ul li a:link,a:hover,a:visited{ font-size:12px; color:#fda701; font-weight:bold; text-decoration:none; padding-top:3px;}
22	.login input{width:60px;}
23	/* -------------- 网页Banner----------- */
24	.top { height:150px; border-top:1px #24A9C6 solid;}
25	/* -------------- 网页导航-------------- */
26	.nav_bg { background-color:#055f98;}
27	.nav { padding:0px;width:1000px; margin:0 auto; }
28	.nav ul li { float:left; line-height:50px;  padding-right:20px; text-indent:35px;}
29	.nav ul li a:link, 
30	.nav ul li a:visited { font-size:16px; color:#fff;text-decoration:none;font-family:"Arial Black", Gadget, sans-serif,"微软雅黑"; font-weight:bold;}
