32	
33	/*图片浏览部分*/
34	.left {width:425px;float:left; padding-top:10px;}
35	#photos {visibility: hidden;}
36	.galleryview {background: rgb(221, 221, 221); padding: 0px; border: 0px solid rgb(170, 170, 170); border-image: none;box-shadow: 6px 6px 5px #ccc;}
37	.loader {background: url("loader.gif") no-repeat center rgb(221, 221, 221);}
38	.panel img{ width:600px; position:absolute; left:-90px;}
39	.panel .panel-overlay {padding: 0px 1em; height: 60px;}
40	.panel .overlay-background {padding: 0px 1em; height: 60px;}
41	.panel .overlay-background {background: rgb(34, 34, 34);}
42	.panel .panel-overlay {	color: white; font-size: 0.7em;}
43	.panel .panel-overlay a {color: white; text-decoration: underline;}
44	.filmstrip {margin: 5px;}
45	.frame .img_wrap {border: 0px solid rgb(170, 170, 170); border-image: none;}
46	.frame.current .img_wrap {border-color: rgb(0, 0, 0);}
47	.frame img {border: currentColor; border-image: none;}
48	.frame .caption {text-align: center; color: rgb(136, 136, 136); font-size: 11px;}
49	.frame.current .caption {color: rgb(0, 0, 0);}
