66	.news_list ul li span { float:left;}
67	.news_list ul li span a:link, 
68	.news_list ul li span a:visited {font-size:13px; color:#000;font-weight: normal; text-decoration:none; }
69	.news_list ul li span a:hover {font-size:13px; color:#fda701; font-weight:normal; text-decoration: none; }
